cd /app/submission && cat > /workspace/tmp/t2.py << 'PY'
import subprocess, json, sys
def run(obj):
    raw=obj if isinstance(obj,(bytes,)) else json.dumps(obj).encode()
    p=subprocess.run([sys.executable,'-I','/app/submission/entry.py'],input=raw,capture_output=True)
    try: return json.loads(p.stdout.decode())
    except: return {'_raw':p.stdout.decode(),'_err':p.stderr.decode()}
def cfg(**kw):
    base=dict(early=False,overlap="reject",buffer_packets=4,idle_ms=0,
              max_streams_bidi=100,max_streams_uni=100,max_stream_data=1000000,
              max_data=1000000000,crypto_limit=1000000,sent={"I":[],"H":[],"A":[]})
    base.update(kw); return base
def req(traces): return {"version":1,"traces":traces}
def tr(tid,config,events): return {"id":tid,"config":config,"events":events}

tests={}
# empty traces
tests['empty']=req([])
# buffer at EOF: H packet queued never installed
tests['buffered_eof']=req([tr("a",cfg(),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"H","pn":0,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# buffer full: buffer_packets=1, two H packets
tests['buffer_full']=req([tr("a",cfg(buffer_packets=1),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[
     {"level":"H","pn":0,"auth":True,"frames":[{"type":"PING"}]},
     {"level":"H","pn":1,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# key discard drops pending
tests['discard_pending']=req([tr("a",cfg(),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"H","pn":0,"auth":True,"frames":[{"type":"PING"}]}]},
  {"t":1,"op":"key","level":"H","action":"discard"},
])])
# layout: A not final
tests['layout']=req([tr("a",cfg(),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[
     {"level":"A","pn":0,"auth":True,"frames":[{"type":"PING"}]},
     {"level":"I","pn":0,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# idle timeout
tests['idle']=req([tr("a",cfg(idle_ms=10),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":0,"auth":True,"frames":[{"type":"PING"}]}]},
  {"t":15,"op":"tick"},
  {"t":20,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":1,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# close app true
tests['close']=req([tr("a",cfg(early=True),[
  {"t":0,"op":"key","level":"A","action":"install"},
  {"t":1,"op":"datagram","bytes":1200,"packets":[{"level":"A","pn":0,"auth":True,"frames":[{"type":"CLOSE","app":True,"code":7},{"type":"PING"}]}]}
])])
# ack valid
tests['ack_ok']=req([tr("a",cfg(sent={"I":[[0,5]],"H":[],"A":[]}),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":9,"auth":True,"frames":[{"type":"ACK","ranges":[[1,3]]}]}]}
])])
# ack not sent -> protocol violation
tests['ack_bad']=req([tr("a",cfg(sent={"I":[[0,5]],"H":[],"A":[]}),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":9,"auth":True,"frames":[{"type":"ACK","ranges":[[1,7]]}]}]}
])])
# ack unsorted -> frame encoding error
tests['ack_unsorted']=req([tr("a",cfg(sent={"I":[[0,100]],"H":[],"A":[]}),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":9,"auth":True,"frames":[{"type":"ACK","ranges":[[5,6],[1,2]]}]}]}
])])
# initial too small
tests['small_initial']=req([tr("a",cfg(),[
  {"t":0,"op":"datagram","bytes":100,"packets":[{"level":"I","pn":0,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# early rejected
tests['early_rejected']=req([tr("a",cfg(early=False),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"Z","pn":0,"auth":True,"frames":[{"type":"PING"}]}]}
])])
# handshake done forbidden
tests['hsdone']=req([tr("a",cfg(),[
  {"t":0,"op":"datagram","bytes":1200,"packets":[{"level":"I","pn":0,"auth":True,"frames":[{"type":"HANDSHAKE_DONE"}]}]}
])])
for name,obj in tests.items():
    print("====",name)
    print(json.dumps(run(obj)))
PY
